#!/usr/bin/env node

const fs = require("fs");
const path = require("path");

const DEVIGN_CSS = `/*
 * ============================================================================
 *   DEVIGN — Custom Theme Overrides
 * ============================================================================
 *
 *   This file was generated by: npx devign init
 *
 *   HOW TO USE
 *   ──────────
 *   1. Change any value below to customize the look of every Devign component.
 *   2. Import this file in your main CSS AFTER the Devign styles:
 *
 *      @import "tailwindcss";
 *      @source "../node_modules/devign/dist";
 *      @import "devign/styles.css";
 *      @import "./devign.css";        ← your overrides
 *
 *   3. Delete any lines you don't need — only keep what you want to change.
 *      Devign will use its defaults for anything you remove.
 *
 *   TIP: Only Layer 1 (palette) overrides are needed for a full retheme.
 *        Layer 2 (semantic) tokens are pre-wired to Layer 1, so they update
 *        automatically. Override Layer 2 only to rewire specific roles.
 *
 *   Docs → https://github.com/SodiqOgundairo/Devign#theming
 * ============================================================================
 */

:root {
  /* ==========================================================================
     LAYER 1 — RAW PALETTE
     Change these to retheme the entire library in one go.
     ========================================================================== */

  /* Primary brand scale — your main color */
  --brand-50: #ede8f7;
  --brand-100: #d4c5f0;
  --brand-200: #a98cdf;
  --brand-300: #7e53ce;
  --brand-400: #6529be;
  --brand-500: #5000ab;          /* ← Main primary color */
  --brand-600: #40008a;
  --brand-700: #300069;
  --brand-800: #200048;
  --brand-900: #1c0636;          /* ← Secondary / dark shade */

  /* Accent scale — your secondary highlight */
  --accent-50: #fdf8ec;
  --accent-300: #f0ce7a;
  --accent-500: #e3b23c;         /* ← Main accent color */
  --accent-700: #bb4d00;         /* ← Ember / dark accent */

  /* Neutral scale — backgrounds, borders, text */
  --neutral-0: #ffffff;
  --neutral-50: #fafafa;
  --neutral-100: #f5f5f5;
  --neutral-200: #e8e8e8;
  --neutral-300: #d4d4d4;
  --neutral-400: #a1a1a1;
  --neutral-500: #6f6d66;
  --neutral-600: #4a4a48;
  --neutral-700: #282826;
  --neutral-800: #1a1a1a;
  --neutral-900: #121212;

  /* Utility colors */
  --color-sky: #4ea5d9;
  --color-success: #16a34a;
  --color-warning: #d97706;
  --color-error: #dc2626;


  /* ==========================================================================
     LAYER 2 — SEMANTIC TOKENS (light mode)
     These map palette colors to component roles. Override only if you want
     to rewire which color plays which role (e.g. make accent the primary).
     ========================================================================== */

  /* Backgrounds */
  --color-background: var(--neutral-100);
  --color-card: var(--neutral-0);
  --color-popover: var(--neutral-0);
  --color-input: var(--neutral-0);
  --color-muted: var(--neutral-100);

  /* Foregrounds */
  --color-foreground: var(--neutral-900);
  --color-card-foreground: var(--neutral-900);
  --color-popover-foreground: var(--neutral-900);
  --color-muted-foreground: var(--neutral-500);

  /* Brand roles */
  --color-primary: var(--brand-500);
  --color-primary-foreground: var(--neutral-50);
  --color-secondary: var(--brand-900);
  --color-secondary-foreground: var(--neutral-50);
  --color-accent: var(--accent-500);
  --color-accent-foreground: var(--neutral-900);
  --color-ember: var(--accent-700);
  --color-ember-foreground: var(--neutral-50);

  /* State colors */
  --color-destructive: var(--color-error);
  --color-destructive-foreground: var(--neutral-50);

  /* Chrome */
  --color-border: var(--neutral-200);
  --color-ring: var(--brand-500);


  /* ==========================================================================
     SHAPE & SPACING
     Override --radius to scale all component border-radii at once.
     ========================================================================== */

  --radius: 12px;               /* Try 8px (angular) or 20px (pill) */


  /* ==========================================================================
     GLASSMORPHISM — LIGHT MODE
     Adjust the blur and transparency for your desired glass effect.
     ========================================================================== */

  --glass-bg: rgba(255, 255, 255, 0.65);
  --glass-bg-strong: rgba(255, 255, 255, 0.85);
  --glass-border: rgba(0, 0, 0, 0.08);
  --glass-card-bg: rgba(255, 255, 255, 0.75);
  --glass-card-border: rgba(0, 0, 0, 0.06);
  --glass-input-bg: rgba(255, 255, 255, 0.55);
  --glass-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.1);
  --glass-card-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.12);
  --glass-blur: 16px;           /* Increase for frosted, decrease for subtle */


  /* ==========================================================================
     SHADOWS
     ========================================================================== */

  --shadow-sm: 0 2px 8px 0 rgba(31, 38, 135, 0.06);
  --shadow-md: 0 4px 16px 0 rgba(31, 38, 135, 0.1);
  --shadow-lg: 0 8px 32px 0 rgba(31, 38, 135, 0.14);
  --shadow-xl: 0 12px 48px 0 rgba(31, 38, 135, 0.18);

  --shadow-primary: 0 4px 16px 0 rgba(80, 0, 171, 0.25);
  --shadow-primary-glow: 0 0 30px rgba(80, 0, 171, 0.3);
  --shadow-accent: 0 4px 16px 0 rgba(227, 178, 60, 0.25);
  --shadow-accent-glow: 0 0 30px rgba(227, 178, 60, 0.3);


  /* ==========================================================================
     TYPOGRAPHY
     Devign does NOT load fonts — bring your own via Google Fonts, Fontsource,
     or local files. Just change the family names below.
     ========================================================================== */

  --font-sans: "Poppins", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Otama EP", ui-serif, Georgia, serif;
  --font-mono: ui-monospace, "Cascadia Code", "Fira Code", monospace;


  /* ==========================================================================
     TRANSITIONS
     Set all to 0ms to disable motion (great for accessibility).
     ========================================================================== */

  --transition-fast: 150ms;
  --transition-normal: 250ms;
  --transition-slow: 350ms;
  --ease-smooth: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-bounce: cubic-bezier(0.68, -0.55, 0.265, 1.55);
  --ease-spring: cubic-bezier(0.175, 0.885, 0.32, 1.275);
}


/* =============================================================================
   DARK MODE OVERRIDES
   These kick in when <html class="dark"> is set.
   Delete this block if you want to keep the default dark theme as-is.
   ============================================================================= */

.dark {
  /* Backgrounds */
  --color-background: var(--neutral-900);
  --color-card: var(--neutral-800);
  --color-popover: var(--neutral-800);
  --color-input: var(--neutral-700);
  --color-muted: var(--neutral-700);

  /* Foregrounds */
  --color-foreground: var(--neutral-50);
  --color-card-foreground: var(--neutral-50);
  --color-popover-foreground: var(--neutral-50);
  --color-muted-foreground: var(--neutral-400);

  /* Chrome */
  --color-border: var(--neutral-700);

  /* Glass — dark variants */
  --glass-bg: rgba(18, 18, 18, 0.65);
  --glass-bg-strong: rgba(18, 18, 18, 0.85);
  --glass-border: rgba(255, 255, 255, 0.08);
  --glass-card-bg: rgba(40, 40, 38, 0.75);
  --glass-card-border: rgba(255, 255, 255, 0.1);
  --glass-input-bg: rgba(40, 40, 38, 0.55);
  --glass-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4);
  --glass-card-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.5);

  /* Shadows — darker */
  --shadow-sm: 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 16px 0 rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 8px 32px 0 rgba(0, 0, 0, 0.5);
  --shadow-xl: 0 12px 48px 0 rgba(0, 0, 0, 0.6);
}
`;

// ---------------------------------------------------------------------------
// CLI logic
// ---------------------------------------------------------------------------

const args = process.argv.slice(2);
const command = args[0];

if (command === "init") {
  // Determine output directory
  let outDir = "src";
  const dirFlag = args.find((a) => a.startsWith("--dir="));
  if (dirFlag) {
    outDir = dirFlag.split("=")[1];
  }

  const outPath = path.resolve(process.cwd(), outDir, "devign.css");

  // Check if file already exists
  if (fs.existsSync(outPath)) {
    console.log(`\n  ⚠  ${outPath} already exists.`);
    console.log(`     Delete it first if you want a fresh copy.\n`);
    process.exit(0);
  }

  // Create directories if needed
  const dir = path.dirname(outPath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
    console.log(`  ✓ Created directory: ${dir}`);
  }

  // Write the file
  fs.writeFileSync(outPath, DEVIGN_CSS, "utf-8");

  console.log(`
  ✓ Created ${path.relative(process.cwd(), outPath)}

  Next steps:
  ───────────
  1. Open ${path.relative(process.cwd(), outPath)} and change any values you like.
  2. Import it in your main CSS file AFTER Devign styles:

     @import "tailwindcss";
     @source "../node_modules/devign/dist";
     @import "devign/styles.css";
     @import "./${path.relative(path.resolve(process.cwd(), outDir), outPath).replace(/\\/g, "/")}";

  3. Delete any lines you don't need — Devign uses its defaults
     for anything you remove.

  Docs → https://github.com/SodiqOgundairo/Devign#theming
`);
} else {
  console.log(`
  Devign CLI
  ──────────

  Usage:
    npx devign init              Generate a devign.css theme file in ./src/
    npx devign init --dir=styles Generate it in a custom directory

  Docs → https://github.com/SodiqOgundairo/Devign#theming
`);
}
